<main class="auth-shell"><section class="card auth-card"><span class="eyebrow">Registrierung 18+</span><h1>Konto erstellen</h1><?php if($errors):?><div class="alert danger"><ul><?php foreach($errors as $e):?><li><?=App\Core\View::e($e)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" class="form-grid"><?=App\Core\Csrf::field()?><label>Vorname<input name="first_name" value="<?=App\Core\View::e($_POST['first_name']??'')?>" required></label><label>Nachname<input name="last_name" value="<?=App\Core\View::e($_POST['last_name']??'')?>" required></label><label>Geburtsdatum<input name="birth_date" type="date" value="<?=App\Core\View::e($_POST['birth_date']??'')?>" required></label><label>Telefonnummer<input name="phone" value="<?=App\Core\View::e($_POST['phone']??'')?>" required></label><label class="full">Straße und Hausnummer<input name="street" value="<?=App\Core\View::e($_POST['street']??'')?>" required></label><label>PLZ<input name="postal_code" value="<?=App\Core\View::e($_POST['postal_code']??'')?>" required></label><label>Ort<input name="city" value="<?=App\Core\View::e($_POST['city']??'')?>" required></label><label class="full">E-Mail-Adresse<input name="email" type="email" value="<?=App\Core\View::e($_POST['email']??'')?>" required></label><label class="full">Passwort<input name="password" type="password" minlength="10" required></label><div class="full consent-list"><?php $checks=['adult_confirm'=>'Ich bestätige, mindestens 18 Jahre alt zu sein.','terms'=>'Ich akzeptiere die Plattformbedingungen.','privacy'=>'Ich habe die Datenschutzhinweise gelesen.','content_rules'=>'Ich akzeptiere die Inhaltsregeln.','evidence_rules'=>'Ich akzeptiere die Nachweisregeln.','shipping_rules'=>'Ich akzeptiere die Versandregeln.','wallet_rules'=>'Ich akzeptiere die Wallet- und Auszahlungsbedingungen.'];foreach($checks as $n=>$t):?><label class="check"><input type="checkbox" name="<?=$n?>" value="1" <?=isset($_POST[$n])?'checked':''?> required><span><?=App\Core\View::e($t)?></span></label><?php endforeach;?></div><button class="btn primary full" type="submit">Registrieren</button></form></section></main>